insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-marchewka-groszek', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-marchewka-groszek/009472cc-9559-425d-9660-aa0ea87b2781.webp', 15, 20, 4, null, null, '{}'::jsonb, '', array['post-sonntagsessen', 'post-polenladen', 'post-ersatzprodukte-de']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-marchewka-groszek', 'de', 'Marchewka z groszkiem', 'marchewka-groszek', 'Warme Möhren-Erbsen-Beilage mit Butterglasur, der ruhige Klassiker neben Schabowy und dem Sonntagsteller.', '[{"text":"Möhren schälen und in gleichmäßige Würfel oder Scheiben von etwa 1 cm schneiden, damit alle Stücke gleichzeitig gar werden. Frische oder tiefgekühlte Erbsen bereitstellen, tiefgekühlte dabei nicht vorher auftauen.","tip":"Das ist eine warme Beilage, kein Rohkostsalat, die [Mizeria](/de/rezepte/mizeria) bleibt kalt mit Gurke, die [Buraczki](/de/rezepte/buraczki) bleiben bei Roter Bete."},{"text":"Möhren in wenig Salzwasser 8 bis 12 Minuten garen, bis sie bissfest-weich sind. Abgießen und etwas Kochwasser für später aufheben.","tip":"Nicht zu weich kochen, die Glasur braucht später noch Struktur, um an den Stücken zu haften. Einkauf für die Zutaten: [Polenladen](/de/blog/polenladen-einkaufen)."},{"text":"In einer Pfanne Butter schmelzen, optional mit einer halben Teelöffel Zucker. Möhren und Erbsen dazugeben und 3 bis 5 Minuten schwenken, bis alles glänzt und die Erbsen heiß sind.","tip":"Der Zucker rundet die natürliche Süße der Möhren ab, ohne die Beilage süß schmecken zu lassen."},{"text":"Mit Salz, Pfeffer und gehacktem Dill oder Petersilie abschmecken. Bei Bedarf 1 bis 2 Esslöffel Kochwasser für Seidenglanz einrühren, eine dicke Soße wie bei einem Eintopf ist hier nicht gewollt.","tip":"Zum Menü passt der [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch), klassisch steht die Beilage neben [Kotlet schabowy](/de/rezepte/kotlet-schabowy)."},{"text":"Sofort heiß servieren. Reste im Kühlschrank aufbewahren und kurz in der Pfanne mit etwas Butter aufwärmen, in der Mikrowelle werden die Möhren dagegen schnell weich statt glänzend.","tip":"Fehlt frischer Dill oder gute Butter, hilft der Beitrag zu [Ersatzprodukten DE](/de/blog/ersatzprodukte-de) weiter."}]'::jsonb, 'Marchewka z groszkiem, süßlich und buttrig, warm glänzend mit Dillgrün, die ruhige Sonntagsbeilage neben Fleisch. Marchewka z groszkiem gilt vielen als uraltes polnisches Hausrezept, hat aber tatsächlich französische Wurzeln: Die Technik, klein geschnittenes Wurzelgemüse in einer leichten Mehlschwitze zu schwenken, stammt aus der klassischen französischen Küche und ähnelt den glasierten carottes Vichy, wie sie unter anderem Auguste Escoffier beschrieb, vermutlich über Köche an polnischen Adelshöfen eingewandert. Ihre bis heute typische Form bekam die Beilage aber erst in der Volksrepublik Polen: Möhren waren das ganze Jahr über billig verfügbar, und mit der industriellen Tiefkühlkost kam der küchenfertige Erbsengroszek in die Kantinen und Bar mleczny genannten Milchbars, wo eine mit Butter geglänzte oder mit Mehl gebundene Gemüseportion half, ein karges Mittagsgericht mit nur wenig Fleisch spürbar sättigender zu machen. Das ist weder der kalte Gurkensalat [Mizeria](/de/rezepte/mizeria) noch die warme Rote-Bete-Beilage [Buraczki](/de/rezepte/buraczki) und auch kein Rohkostsalat. Wie der Teller am Sonntag zusammenkommt, beschreibt der [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch), klassischer Nachbar auf dem Teller ist [Kotlet schabowy](/de/rezepte/kotlet-schabowy).

## Einkaufen und kochen

Möhren und Erbsen, frisch oder tiefgekühlt, Butter, optional eine Prise Zucker sowie Dill oder Petersilie, Salz und Pfeffer reichen völlig aus, das liegt im deutschen Supermarkt bereit, frischen Dill findest du oft im [Polenladen](/de/blog/polenladen-einkaufen). Fehlt Butter oder gutes Kraut, hilft der Beitrag zu [Ersatzprodukten DE](/de/blog/ersatzprodukte-de). Wer Gurke mit Śmietana möchte, kocht [Mizeria](/de/rezepte/mizeria), wer Rote Bete warm mag, [Buraczki](/de/rezepte/buraczki), den Menürahmen setzt der [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch).

Schneide die Möhren gleichmäßig, damit sie zeitgleich gar werden. Mit wenig Wasser bissfest garen und gut abgießen, denn zerkochte Möhren zerfallen später beim Schwenken in der Butter. In der Pfanne Butter schmelzen, optional mit einer Prise Zucker, dann Erbsen und Möhren schwenken, bis sie glänzen, den Dill erst am Ende darunterheben, damit sein Aroma nicht verkocht. Es braucht keine dicke Mehlsoße und keine Mayonnaise, das gehört zu Salaten wie [Mizeria](/de/rezepte/mizeria), plane die Beilage parallel zu [Schabowy](/de/rezepte/kotlet-schabowy) oder einem Braten, denn offen und lauwarm stehend verliert sie schnell ihren Glanz.

Tiefkühlerbsen und vorgeschnittene Möhrenwürfel retten den Sonntag nach Schichtarbeit, das darf man ehrlich so sagen, so wie schon die Kantinen der Volksrepublik von industrieller Tiefkühlkost profitierten. Kinder können Dill hacken, die heiße Pfanne bleibt bei Erwachsenen. Reste am Folgetag kurz mit Butter in der Pfanne aufwärmen. Speiseplan und Sonntagskultur bleiben beim [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch), Zutatenhilfe findest du unter [Ersatzprodukte DE](/de/blog/ersatzprodukte-de) und im [Polenladen](/de/blog/polenladen-einkaufen).

## Am Tisch

Serviere heiß in einer Schüssel oder direkt neben [Kotlet schabowy](/de/rezepte/kotlet-schabowy), Kartoffeln oder Kasza, am Sonntagstisch ordnet der [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch) den Überblick. Verwechsele die Beilage nicht mit [Buraczki](/de/rezepte/buraczki) oder [Mizeria](/de/rezepte/mizeria), beide unterscheiden sich in Farbe, Temperatur und Charakter deutlich. Zutaten mit Charakter findest du im [Polenladen](/de/blog/polenladen-einkaufen).

Roh oder als Surówka serviert verfehlt die warme Beilage, wer [Mizeria](/de/rezepte/mizeria) oder [Buraczki](/de/rezepte/buraczki) kocht, hat ohnehin ein anderes Gericht vor sich. Zu langes Kochen macht Brei statt Glanz, und zu wenig Butter nimmt der Beilage genau den Charakter, der sie von einer reinen Gemüsebeilage unterscheidet.

Du kannst nur Möhren mit Butter machen, Petersilie statt Dill nehmen oder die Prise Zucker weglassen. Passende Nachbar-Beilagen sind [Mizeria](/de/rezepte/mizeria), [Buraczki](/de/rezepte/buraczki) und [Kapusta zasmażana](/de/rezepte/kapusta-zasmażana), zum Fleisch passt [Schabowy](/de/rezepte/kotlet-schabowy), Orientierung geben der [Sonntagsessen-Guide](/de/blog/sonntagsessen-polnisch), der [Polenladen](/de/blog/polenladen-einkaufen) und die [Ersatzprodukte DE](/de/blog/ersatzprodukte-de).', 'Marchewka z groszkiem Rezept | Möhren Erbsen Beilage | Alemniam', 'Marchewka z groszkiem: warme Möhren und Erbsen mit Butter, eine polnische Sonntagsbeilage, anders als Mizeria oder Buraczki.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-marchewka-groszek', 'pl', 'Marchewka z groszkiem', 'marchewka-groszek', 'Ciepły dodatek z marchewki i groszku w maśle, spokojny klasyk obok schabowego i niedzielnego talerza.', '[{"text":"Marchewkę obierz i pokrój w równe kostki lub plasterki, około 1 cm, żeby wszystkie kawałki ugotowały się jednocześnie. Przygotuj świeży lub mrożony groszek, mrożonego nie rozmrażaj wcześniej.","tip":"To ciepły dodatek, nie surówka, [mizeria](/pl/rezepte/mizeria) zostaje zimna z ogórkiem, [buraczki](/pl/rezepte/buraczki) zostają przy burakach."},{"text":"Marchewkę gotuj w małej ilości osolonej wody 8 do 12 minut, aż będzie miękka, ale wciąż lekko twarda w środku. Odcedź i zachowaj odrobinę wody z gotowania na później.","tip":"Nie rozgotuj marchewki, glazura potrzebuje jeszcze trochę struktury, żeby przylegać do kawałków. Zakupy do przepisu: [sklep polski](/pl/blog/sklep-polski-zakupy)."},{"text":"Na patelni rozpuść masło, opcjonalnie z pół łyżeczki cukru. Dodaj marchewkę i groszek, smaż 3 do 5 minut, aż wszystko nabierze połysku, a groszek będzie gorący.","tip":"Cukier wygładza naturalną słodycz marchewki, bez sprawiania, że dodatek smakuje słodko."},{"text":"Dopraw solą, pieprzem i siekanym koprem lub pietruszką. W razie potrzeby wmieszaj 1 do 2 łyżek wody z gotowania dla połysku, gęsty sos jak w gulaszu nie jest tu potrzebny.","tip":"Do menu pasuje [obiad niedzielny](/pl/blog/obiad-niedzielny), klasycznie dodatek stoi obok [kotleta schabowego](/pl/rezepte/kotlet-schabowy)."},{"text":"Podawaj od razu gorące. Resztki przechowuj w lodówce i krótko podgrzej na patelni z odrobiną masła, w mikrofalówce marchewka szybko robi się miękka, ale traci połysk.","tip":"Brak świeżego koperku lub dobrego masła uzupełniają [zamienniki składników](/pl/blog/zamienniki-skladnikow)."}]'::jsonb, 'Marchewka z groszkiem, maślano-słodkawa, ciepła i błyszcząca, z koprem, spokojny dodatek niedzielny obok mięsa. Wiele osób uważa marchewkę z groszkiem za prastary, staropolski przepis, ale w rzeczywistości ma korzenie francuskie: technika duszenia drobno pokrojonych warzyw korzeniowych w lekkiej zasmażce pochodzi z klasycznej kuchni francuskiej i przypomina glazurowane carottes Vichy, opisywane między innymi przez Auguste''a Escoffiera, prawdopodobnie przywiezione przez kucharzy działających na polskich dworach magnackich. Swoją dzisiejszą, znaną wszystkim formę dodatek zyskał jednak w Polskiej Rzeczypospolitej Ludowej: marchew była tania i dostępna cały rok, a wraz z przemysłem mrożonek do stołówek i barów mlecznych trafił gotowy groszek, dzięki czemu błyszcząca od masła albo zagęszczona mąką porcja warzyw pomagała skromnemu obiadowi z niewielką ilością mięsa wydawać się bardziej sycącym. To ani zimna [mizeria](/pl/rezepte/mizeria), ani ciepłe [buraczki](/pl/rezepte/buraczki), ani surowa surówka. Jak ułożyć niedzielny talerz, opisuje [obiad niedzielny](/pl/blog/obiad-niedzielny), klasyczny sąsiad to [kotlet schabowy](/pl/rezepte/kotlet-schabowy).

## Zakupy i gotowanie

Marchew i groszek, świeże lub mrożone, masło, opcjonalnie szczypta cukru oraz koper lub pietruszka, sól i pieprz w pełni wystarczą, baza jest w każdym markecie, świeży koper często w [sklepie polskim](/pl/blog/sklep-polski-zakupy). Brak masła lub dobrych ziół uzupełnią [zamienniki składników](/pl/blog/zamienniki-skladnikow). Kto chce ogórek ze śmietaną, gotuje [mizerię](/pl/rezepte/mizeria), kto ciepłe buraczki, [buraczki](/pl/rezepte/buraczki), ramę menu daje [obiad niedzielny](/pl/blog/obiad-niedzielny).

Kroj marchewkę równo, żeby gotowała się jednocześnie. Gotuj w małej ilości wody al dente i dobrze odcedź, bo rozgotowana marchewka rozpadnie się później podczas duszenia w maśle. Na patelni rozpuść masło, opcjonalnie ze szczyptą cukru, potem zeszklij groszek i marchewkę do połysku, koper dodaj na końcu, żeby jego aromat nie wyparował podczas gotowania. Nie potrzeba gęstego sosu z mąki ani majonezu, to domena sałatek jak [mizeria](/pl/rezepte/mizeria), planuj dodatek równolegle do [schabowego](/pl/rezepte/kotlet-schabowy) lub pieczenia, bo stojąc długo na blacie szybko traci połysk.

Mrożony groszek i przygotowana kostka marchewki ratują niedzielę po zmianie, warto to nazwać uczciwie, podobnie jak kantyny w PRL korzystały z przemysłowych mrożonek. Dzieci mogą siekać koper, gorąca patelnia zostaje u dorosłych. Resztki nazajutrz krótko podsmaż z masłem. Kulturę niedzieli opisuje [obiad niedzielny](/pl/blog/obiad-niedzielny), pomoc przy składnikach dają [zamienniki składników](/pl/blog/zamienniki-skladnikow) i [sklep polski](/pl/blog/sklep-polski-zakupy).

## Przy stole

Podawaj gorące w misce albo obok [schabowego](/pl/rezepte/kotlet-schabowy), ziemniaków lub kaszy, niedzielny przegląd daje [obiad niedzielny](/pl/blog/obiad-niedzielny). Nie myl dodatku z [buraczkami](/pl/rezepte/buraczki) ani z [mizerią](/pl/rezepte/mizeria), obie różnią się wyraźnie kolorem, temperaturą i charakterem. Specjalności kupisz w [sklepie polskim](/pl/blog/sklep-polski-zakupy).

Podanie na surowo albo jako surówka mija się z ciepłym dodatkiem, [mizeria](/pl/rezepte/mizeria) i [buraczki](/pl/rezepte/buraczki) to i tak osobne dania. Zbyt długie gotowanie robi papkę zamiast połysku, a za mało masła odbiera dodatkowi właśnie ten charakter, który odróżnia go od zwykłych gotowanych warzyw.

Możesz zrobić samą marchewkę z masłem, wziąć pietruszkę zamiast kopru albo pominąć cukier. Pasujące dodatki to [mizeria](/pl/rezepte/mizeria), [buraczki](/pl/rezepte/buraczki) i [kapusta zasmażana](/pl/rezepte/kapusta-zasmażana), do mięsa pasuje [schabowy](/pl/rezepte/kotlet-schabowy), orientację dają [obiad niedzielny](/pl/blog/obiad-niedzielny), [sklep polski](/pl/blog/sklep-polski-zakupy) i [zamienniki składników](/pl/blog/zamienniki-skladnikow).', 'Marchewka z groszkiem przepis | Ciepły dodatek | Alemniam', 'Marchewka z groszkiem: ciepła marchewka i groszek z masłem, niedzielny dodatek, inny niż mizeria czy buraczki.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
